INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('2e018b03-2663-5f67-8e6f-d1327b2894e2'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 0, 'Industry, Role & Course Readiness', 'Learner connects front-office arrival readiness to guest trust, room flow, payment/readiness safety, team workload, and L1 role boundaries before working the case.', '["Tired guest waiting at 3:30 PM", "Growing front-desk queue", "Early-arrival request", "Payment/readiness uncertainty", "Room is clean but not inspection-cleared", "Pressure to act before checking evidence"]'::jsonb, '["May treat guest urgency as permission to proceed", "May assume a clean room is access-ready", "May accept a payment claim as proof", "May confuse helpful service with approval authority", "May not know which evidence must be checked first"]'::jsonb, 'Front-office teams must protect guest trust and service flow while coordinating reservation, identity, payment, room-status, SOP, and handoff evidence across different owners without allowing premature access.', '["Basic awareness of hotel or reception operations", "Ability to read simple records and status notes", "No prior operational experience required"]'::jsonb, '["Why arrival-readiness evidence matters", "How to identify the main evidence types", "How L1 authority differs from supervisor approval", "How to recognize risk before action", "How to write one open validation question"]'::jsonb, 'Use before entering an arrival case or taking any check-in, room-access, or visitor-entry step when readiness evidence is incomplete, mixed, or unclear.', '{"major_concepts": "Front-office arrival readiness, evidence-before-action, L1 role boundary, guest trust, room-flow safety, payment/readiness safety, and service-handoff evidence", "implementation_context_when_to_use": "Use at the start of a guest or visitor arrival situation before any check-in, access, or readiness recommendation is made", "reason_behind_concept": "Prevents premature action, protects the guest and property, reduces payment and room-flow errors, and establishes the evidence baseline for the course"}'::jsonb, '{"ai_support_tips": "After writing one human observation and one open question, use AI to simplify SOP language, compare evidence categories, or test whether wording crosses L1 authority; never use AI to approve check-in or access", "module_continuity_link": "The Course Readiness Sheet becomes the role-boundary, risk, evidence-source, and validation-question baseline for Module 1 Case Intake"}'::jsonb, '{"technical_concepts_learnt": "Reservation evidence, identity evidence, PMS/payment notes, room-status signals, SOP controls, handoff records, access restrictions, and L1 authority boundaries", "academic_refresher_concepts": "Hotel organization, rooms division, reservation and registration basics, guest services, room-status terminology, and front-office workflow"}'::jsonb, 'At 3:30 PM, a tired guest is waiting near the front desk while the queue grows. The learner sees a reservation for Rohan Mehta, an early-arrival note, payment/readiness uncertainty, and a room that is not yet fully inspection-cleared. Before touching any check-in or access step, the learner must identify the course mission, L1 role boundary, tools, risks, and one open validation question.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('df2d80be-e296-5bda-901e-0869b8f2491e'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 1, 'Case Intake & Role Boundary', 'Learner opens the arrival case, separates facts from assumptions, identifies available/missing records, and protects L1 authority while preparing intake.', '["Guest says payment is complete", "Guest is tired and expects immediate action", "Reservation and ID names vary slightly", "PMS shows payment hold", "Room 412 is clean but not inspected", "Multiple evidence sources must be captured quickly"]'::jsonb, '["May record the guest claim as a confirmed fact", "May ignore the ID-name variation", "May overlook the PMS hold", "May assume room status is ready", "May mix assumptions with evidence", "May promise access while collecting information"]'::jsonb, 'Front-office intake must create a reliable case record from fragmented guest statements and system evidence so that the next reviewer can act without repeating work or inheriting hidden assumptions.', '["Completed Module 0 Course Readiness Sheet", "Understands the L1 allowed and prohibited actions", "Can identify reservation, ID, PMS/payment, room-status, and handoff evidence"]'::jsonb, '["How to separate facts, claims, assumptions, and missing information", "How to capture reservation and ID evidence", "How to record PMS and room-status signals", "How to ask safe clarification questions", "When supervisor review is required"]'::jsonb, 'Use during the first structured intake of a guest or visitor arrival case, especially when the person is waiting and the available records do not fully agree.', '{"major_concepts": "Evidence-led case intake, fact-versus-claim classification, assumption control, missing-information capture, clarification questions, and L1 role-boundary protection", "implementation_context_when_to_use": "Use when opening an arrival case and converting reservation, ID, guest statement, PMS, and room-status inputs into a reviewable Case Intake Note", "reason_behind_concept": "A clean intake prevents guest pressure or memory from becoming false evidence and gives validation work a complete, traceable starting point"}'::jsonb, '{"ai_support_tips": "Use AI only after drafting the intake note to test whether each statement is a fact, claim, assumption, or missing item and to improve neutral wording; do not let AI invent evidence or decide readiness", "module_continuity_link": "The confirmed facts, assumptions, missing information, and clarification questions become the evidence set for Module 2 validation"}'::jsonb, '{"technical_concepts_learnt": "Reservation-card fields, masked ID evidence, PMS notes, payment-hold indicators, room-status signals, claim tagging, missing-data identification, and supervisor-review triggers", "academic_refresher_concepts": "Reservation processing, guest registration, front-office records, active listening, customer communication, and basic documentation discipline"}'::jsonb, 'The learner receives the first case file. Reservation card shows guest name Rohan Mehta, OTA source, today arrival, early arrival requested. Masked ID evidence shows Rohan M. The guest says payment is complete. PMS note says payment hold pending. Room board says Room 412 clean - not inspected. Learner must separate facts, assumptions, missing information, and role boundary.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('6549115e-08da-53bb-a2d8-4c1f40cda084'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 2, 'Evidence / Requirement Validation', 'Learner validates whether reservation, identity, room-status, and payment/readiness evidence is complete, matching, missing, blocked, or requires supervisor review.', '["Evidence looks almost ready", "Minor ID variation may appear harmless", "Guest claim conflicts with PMS hold", "Clean room may be mistaken for inspected room", "Missing inspection timestamp", "Pressure to convert mixed evidence into a quick ready/not-ready answer"]'::jsonb, '["May classify a minor variation as a full match", "May treat payment claim as approved evidence", "May mark clean-not-inspected as ready", "May ignore missing timestamps", "May use personal judgment instead of status categories", "May recommend access despite blockers"]'::jsonb, 'Arrival-readiness decisions depend on consistent evidence classification because small mismatches, missing controls, and unresolved holds can create payment, privacy, room-safety, and access risks.', '["Completed Module 1 Case Intake Note", "Facts, claims, assumptions, and missing information are separated", "All visible reservation, ID, payment, room-status, and SOP evidence is available for review"]'::jsonb, '["How to classify match, minor variation, mismatch, missing, and hold/blocker", "How observed and expected values differ", "How to identify impact and owner/review need", "How to flag risk", "How to recommend a safe next step without approving access"]'::jsonb, 'Use after case intake and before any readiness recommendation, handoff, check-in progression, room allocation, key release, or visitor access decision.', '{"major_concepts": "Evidence validation categories, observed-versus-expected comparison, blocker classification, evidence reason, impact analysis, risk flagging, owner/review need, and safe next step", "implementation_context_when_to_use": "Use when reservation, identity, payment, room-status, or inspection evidence must be judged as matching, varied, missing, blocked, or requiring review", "reason_behind_concept": "Consistent validation prevents almost-ready evidence from being mistaken for approved readiness and makes each recommendation traceable to a source"}'::jsonb, '{"ai_support_tips": "After completing the first checklist attempt, use AI to challenge unsupported ready decisions, ask for the evidence source behind each status, and improve privacy-safe wording; AI must not override SOP or supervisor review", "module_continuity_link": "Confirmed evidence, blockers, risks, and owner/review needs become the basis for the Module 3 Action or Handoff Note"}'::jsonb, '{"technical_concepts_learnt": "Match, minor variation, mismatch, missing, hold/blocker, observed and expected values, inspection status, payment hold, risk flag, owner routing, and validation evidence trail", "academic_refresher_concepts": "Record comparison, exception identification, room-status control, payment-status awareness, checklist use, and basic quality-control reasoning"}'::jsonb, 'The learner must validate whether the case evidence is complete and usable. Reservation name Rohan Mehta and ID name Rohan M. may be a minor variation, but payment hold pending and Room 412 clean-not-inspected are blockers. Learner must mark each signal as match, minor variation, mismatch, missing, or hold/blocker.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('b6606c1e-a0fd-505f-ba6c-d96e07150bba'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 3, 'Guided Work Action or Handoff', 'Learner turns validated evidence into a role-safe recommendation or handoff without approving check-in or releasing access.', '["Guest is still waiting", "Validated blockers remain unresolved", "Front desk must communicate clearly", "Correct owner may not be immediately available", "Pressure to sound decisive", "Risk of using approval or release language"]'::jsonb, '["May copy the checklist instead of creating an actionable handoff", "May use vague owner labels", "May recommend check-in instead of review", "May omit the action L1 cannot take", "May overpromise to the guest", "May leave the next owner without a clear request"]'::jsonb, 'A handoff must transfer enough evidence, risk, ownership, and next-step clarity for another employee to act quickly while preserving accountability and authority boundaries.', '["Completed Module 2 Evidence Validation Checklist", "Confirmed evidence and unresolved blockers are identified", "Risk and owner/review needs are visible"]'::jsonb, '["How to structure an evidence-backed handoff", "How recommendation differs from approval", "How to name the blocker, risk, owner, and safe next step", "How to state prohibited L1 action", "How to communicate safely with the guest and internal owner"]'::jsonb, 'Use after validation when the case requires supervisor, payment, housekeeping, security, host, or another owner to review or complete the next action.', '{"major_concepts": "Role-safe handoff structure, evidence summary, blocker and risk visibility, owner-specific routing, recommendation-versus-approval language, prohibited L1 action, guest communication, and internal handoff wording", "implementation_context_when_to_use": "Use when validated arrival evidence must be transferred to the correct owner without releasing access or pretending the case is resolved", "reason_behind_concept": "A structured handoff reduces repeated investigation, protects authority, and gives the next owner a clear, evidence-backed action request"}'::jsonb, '{"ai_support_tips": "After drafting the handoff, use AI to check whether it includes guest/case, evidence, blocker, risk, owner, request, action not allowed, and promise-safe wording; reject any AI wording that implies approval or access release", "module_continuity_link": "The recommendation, unresolved risk, owner route, and action-not-allowed statement become the starting inputs for Module 4 escalation"}'::jsonb, '{"technical_concepts_learnt": "Handoff-note fields, owner routing, evidence-to-action traceability, recommendation language, approval boundary, access-release restriction, internal request wording, and guest-safe status communication", "academic_refresher_concepts": "Business communication, delegation and handoff, responsibility and authority, service coordination, documentation clarity, and professional tone"}'::jsonb, 'The learner has a completed validation checklist and must prepare a role-safe handoff note. The note must recommend supervisor review, show evidence, identify blockers, name owner, and state action not allowed for L1. Learner must not approve check-in or release key/access.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('75003941-b763-5c96-9fff-c47c6e00a5b5'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 4, 'Exceptions, Blockers, Risks & Escalations', 'Learner identifies exceptions, blockers, dependency risks, wrong-owner routes, and pressure traps, then escalates with evidence and safe next step.', '["Guest waiting time is increasing", "Queue has grown", "Housekeeping has not confirmed inspection", "Payment hold remains", "Supervisor is temporarily unavailable", "Pressure to bypass controls for service speed"]'::jsonb, '["May treat every issue as urgent", "May escalate without naming the owner", "May hide blockers to reduce conflict", "May confuse escalation with transferring responsibility", "May let empathy become a promise", "May bypass evidence because the queue is growing"]'::jsonb, 'Hospitality teams must manage service pressure without weakening identity, payment, room-readiness, and access controls; escalations must be specific enough for the owner to act immediately.', '["Completed Module 3 Action or Handoff Note", "Unresolved blockers, risks, and likely owners are identified", "Learner understands the no-bypass L1 boundary"]'::jsonb, '["How to distinguish issue, blocker, risk, owner, urgency, and safe next step", "How to identify consequences if a blocker is ignored", "How to select an escalation route", "How to write an actionable escalation note", "How to remain calm and promise-safe under pressure"]'::jsonb, 'Use when a validated blocker remains unresolved, service pressure is increasing, the correct owner must intervene, or proceeding would create identity, payment, room, or access risk.', '{"major_concepts": "Exception classification, blocker-versus-risk distinction, consequence analysis, owner and escalation route, urgency, safe next step, no-bypass control, follow-up, and pressure-safe communication", "implementation_context_when_to_use": "Use when unresolved evidence prevents safe progression and the case must be escalated to a supervisor or specialist owner", "reason_behind_concept": "Evidence-backed escalation protects service flow and safety by making the blocker, consequence, urgency, and required owner action visible instead of relying on verbal pressure"}'::jsonb, '{"ai_support_tips": "After writing the escalation note, use AI to test whether the blocker, evidence, consequence, owner, urgency, request, and safe next step are explicit and calm; AI must not downgrade a blocker or suggest bypassing controls", "module_continuity_link": "The risk, escalation owner, follow-up status, and safe next step become the unresolved-status inputs for Module 5 quality and closure"}'::jsonb, '{"technical_concepts_learnt": "Exception and blocker categories, escalation matrix logic, urgency levels, consequence statements, owner routing, follow-up status, no-bypass wording, and pressure-safe escalation records", "academic_refresher_concepts": "Risk management basics, escalation pathways, conflict handling, service recovery, empathy, accountability, and professional communication under pressure"}'::jsonb, 'The guest is still waiting, the queue has grown, housekeeping has not updated inspection status, and the payment hold is still visible. Learner must escalate the right blocker to the right owner with evidence and urgency, without letting pressure cause unsafe access or false reassurance.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('3d7514ef-3b3f-551d-b87d-72717114909d'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 5, 'Quality, Communication & Closure', 'Learner checks whether L1 work is clear, complete, safe, and ready for review/closure while distinguishing completed work from unresolved risks.', '["Desire to mark the case complete", "Some L1 checks are finished", "Owner actions may still be pending", "Guest needs a clear update", "Access remains restricted", "Pressure to use positive closure language despite unresolved risk"]'::jsonb, '["May confuse completion of L1 work with resolution of the full case", "May omit remaining risk", "May state ready or approved", "May hide pending owner action", "May close without an evidence trail", "May write a vague status update that the next owner cannot use"]'::jsonb, 'Operational records must distinguish completed frontline work from unresolved owner decisions so that guests receive truthful communication and the next shift or reviewer can reconstruct the case.', '["Completed Module 4 Risk and Escalation Note", "L1 checks, unresolved blockers, pending owner actions, communication, and follow-up status are documented"]'::jsonb, '["How responsible closure differs from full resolution", "How to report completed checks and unresolved blockers", "How to record pending owner action and remaining risk", "How to state no-access status", "How to create a clear evidence trail and closure recommendation"]'::jsonb, 'Use after completing the learner’s L1 contribution, before handing the case to another owner, ending a shift, saving portfolio evidence, or communicating that the case remains open.', '{"major_concepts": "Responsible closure, L1-complete versus case-resolved status, pending owner action, no-access statement, remaining-risk visibility, closure recommendation, evidence trail, and quality self-review", "implementation_context_when_to_use": "Use when frontline checks and documentation are complete but payment, room readiness, access, or supervisor action may still be unresolved", "reason_behind_concept": "Truthful closure prevents unsafe assumptions, preserves audit and handoff continuity, and makes unresolved responsibility visible to the next owner"}'::jsonb, '{"ai_support_tips": "After drafting the report, use AI to identify false-closure wording, missing risks, vague owner actions, and unclear no-access statements; AI must not convert L1 completion into check-in or access approval", "module_continuity_link": "The completed checks, remaining risk, pending owner action, and evidence trail become the portfolio proof inputs for Module 6"}'::jsonb, '{"technical_concepts_learnt": "Closure status categories, completed-check record, unresolved-blocker log, pending-owner action, no-access statement, remaining-risk communication, evidence trail, and closure recommendation", "academic_refresher_concepts": "Quality assurance, record completeness, status reporting, continuity of operations, audit trail, self-review, and professional closure communication"}'::jsonb, 'The learner must prepare closure status without pretending the case is solved. Supervisor review has been requested, but payment hold and room inspection may still be pending. Learner must separate completed L1 work from unresolved owner action and write truthful closure for handoff/review.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."modules" ("id", "course_id", "module_no", "title", "description", "pressure_points", "user_confusion", "industry_challenge", "prerequisites", "what_youll_learn", "when_to_apply", "learning_content", "support", "knowledge", "module_problem_statement", "tools", "is_published", "is_active")
VALUES ('635864f6-1f2c-5e4c-ae2e-06ffef18a321'::uuid, '0a010796-10c0-5287-b89a-6ab56bd71399'::uuid, 6, 'Portfolio, Transfer & Final Validation', 'Learner assembles evidence chain, defends decisions, applies same logic to a new visitor readiness case, and proves guided L1 capability.', '["Must prove reasoning rather than only completion", "Seven artifacts must form one evidence chain", "New visitor case changes the evidence context", "Missing host confirmation", "Minor visitor ID variation", "Pressure to reuse guest logic without adapting authority limits"]'::jsonb, '["May submit artifacts without explaining decisions", "May treat portfolio as a file list", "May copy guest check-in logic into visitor access", "May ignore host confirmation", "May fail to show improvement", "May describe concepts without linking evidence to action and boundary"]'::jsonb, 'Employers need evidence that a learner can transfer a safe readiness method to a new case, defend decisions, show improvement, and maintain role boundaries across guest and visitor scenarios.', '["Completed and revised Module 0-5 artifacts", "Understands the complete evidence-to-decision chain", "Can explain L1 authority and escalation logic", "Ready to apply the method to the Anika Rao visitor case"]'::jsonb, '["How to assemble an artifact-chain index", "How to link evidence to decisions and artifact fields", "How to defend role boundaries", "How to show improvement through revisions", "How to transfer the readiness method to a visitor case", "How to present final capability proof"]'::jsonb, 'Use at final course validation, portfolio review, interview preparation, supervisor review, or when applying the same evidence-readiness method to a new guest or visitor case.', '{"major_concepts": "Artifact-chain indexing, evidence-to-decision traceability, decision defence, role-boundary proof, improvement proof, guest-to-visitor transfer, host-confirmation risk, visitor escalation, and final capability reflection", "implementation_context_when_to_use": "Use when consolidating course evidence and demonstrating that the learner can adapt the same safe method to a new visitor-arrival situation", "reason_behind_concept": "Capability is proven through traceable decisions, transfer, and improvement—not by artifact completion alone—and employers need evidence that the learner can generalize without overstepping authority"}'::jsonb, '{"ai_support_tips": "After assembling the portfolio and writing the first defence, use AI to check evidence-to-decision links, missing transfer logic, weak boundary proof, and unclear improvement evidence; AI must not create missing artifacts or independently approve guest or visitor access", "module_continuity_link": "The Final Portfolio Pack becomes the course-level capability proof for review, interview discussion, and future guided arrival-readiness work"}'::jsonb, '{"technical_concepts_learnt": "Artifact indexing, decision traceability, portfolio QA, visitor evidence, host-confirmation control, visitor access boundary, transfer reasoning, decision defence, and improvement evidence", "academic_refresher_concepts": "Reflective learning, portfolio presentation, transfer of learning, evidence-based explanation, professional self-assessment, and interview storytelling"}'::jsonb, 'The learner assembles portfolio proof and then applies the same readiness method to a new visitor case: corporate visitor Anika Rao arrives for a meeting with guest/company contact, but host confirmation is missing and ID has a minor spelling variation. Learner must defend evidence logic and transfer role-safe escalation without treating visitor access like guest check-in approval.', 'null'::jsonb, FALSE, TRUE)
ON CONFLICT DO NOTHING;

COMMIT;
